package com.externalvisuals.setting;
public class SliderSetting extends Setting<Double>{private final double min,max,step; public SliderSetting(String n,double v,double min,double max,double step){super(n,Math.max(min,Math.min(max,v)));this.min=min;this.max=max;this.step=step;} public double getMin(){return min;} public double getMax(){return max;} public double getPercentage(){return max<=min?0:(getValue()-min)/(max-min);} public void setSliderValue(double v){double x=Math.max(min,Math.min(max,v)); if(step>0)x=min+Math.round((x-min)/step)*step;setValue(Math.max(min,Math.min(max,x)));}}
